!function(t){function r(r){for(var e,a,p=r[0],s=r[1],o=r[2],c=0,g=[];c<p.length;c++)a=p[c],Object.prototype.hasOwnProperty.call(m,a)&&m[a]&&g.push(m[a][0]),m[a]=0;for(e in s)Object.prototype.hasOwnProperty.call(s,e)&&(t[e]=s[e]);for(u&&u(r);g.length;)g.shift()();return n.push.apply(n,o||[]),i()}function i(){for(var t,r=0;r<n.length;r++){for(var i,a=n[r],p=!0,s=1;s<a.length;s++)i=a[s],0!==m[i]&&(p=!1);p&&(n.splice(r--,1),t=e(e.s=a[0]))}return t}function e(r){if(a[r])return a[r].exports;var i=a[r]={i:r,l:!1,exports:{}};return t[r].call(i.exports,i,i.exports,e),i.l=!0,i.exports}var a={},m={18:0},n=[];e.m=t,e.c=a,e.d=function(t,r,i){e.o(t,r)||Object.defineProperty(t,r,{enumerable:!0,get:i})},e.r=function(t){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(t,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(t,"__esModule",{value:!0})},e.t=function(t,r){if(1&r&&(t=e(t)),8&r)return t;if(4&r&&"object"==typeof t&&t&&t.__esModule)return t;var i=Object.create(null);if(e.r(i),Object.defineProperty(i,"default",{enumerable:!0,value:t}),2&r&&"string"!=typeof t)for(var a in t)e.d(i,a,function(r){return t[r]}.bind(null,a));return i},e.n=function(t){var r=t&&t.__esModule?function(){return t.default}:function(){return t};return e.d(r,"a",r),r},e.o=function(t,r){return Object.prototype.hasOwnProperty.call(t,r)},e.p="";var p=window.webpackJsonp=window.webpackJsonp||[],s=p.push.bind(p);p.push=r,p=p.slice();for(var o=0;o<p.length;o++)r(p[o]);var u=s;n.push([55,0]),i()}({55:function(t,r,i){"use strict";i.r(r);var e=i(0);Object(e.a)("us","army",i(56),i(1))},56:function(t){t.exports=JSON.parse('{"category":[{"name":"美国","link":"us_shortcut"},{"name":"陆战武器","link":"us_army"},{"name":"军用卡车与军用小车","link":"us_army#us_army_mt"}],"model":"威利MB吉普车","description":"<h6>综述：</h6><p>威利MB吉普车是美国大兵在二战期间引以为荣的轻型越野车，它结构简单，车身低矮，没装车门和上车盖（可加帆布遮盖），该车为四轮驱动，使用低压轮胎，在泥泞中行驶自如，机动性能很好，因而广泛被美军用于传令、侦察、联络用；该车常会加装重机枪、火箭发射器以及小口径火炮等武器作火力防护，也可改装为战场救护车用；不少美军军官都喜欢用其作为自己的指挥座驾；由于该车有很强的过载能力，所以也经常用牵引火炮，用途十分广泛。</p><p>威利MB吉普车在1940年由美国的威利和福特公司开始生产，至二战结束时产量已有60多万辆，除美军大量使用外，还有不少装备了各国盟军，在二战中名声显赫，曾被美军高官感言为赢得二战胜利的三大武器其中之一。</p>","part1title":"系列型号","part1description":"","part1content":[{"image":"imgs/us/army/us_army_mtMB_11.jpg","description":"<h6>威利MB吉普车（Willys MB Jeep）</h6><p>基本技术数据：</p><p>车长：3.36米，车宽：1.57米，车高：1.77米；</p><p>车总重：0.896吨；（自重0.596吨，有效载荷0.3吨）</p><p>（注：因生产厂家、批次的不同与配置各异，车的规格与重量数据会各有不同）</p><p>发动机功率：60匹马力；</p><p>公路最高车速：105千米；</p><p>最大行程：483千米。</p>","caption":""}],"part2title":"战场上的威利MB吉普车","part2description":"","part2content":[{"image":"imgs/us/army/us_army_mtMB_21.jpg","description":"1943年7月，意大利西西里岛，隶属美军第13野战炮兵部队的一辆威利吉普车。","caption":""},{"image":"imgs/us/army/us_army_mtMB_22.jpg","description":"1945年5月，德国地区，隶属美军第16装甲师第5坦克营第803连的一辆威利吉普车，车上安装了一挺12.7mm口径M2重机枪。","caption":""},{"image":"imgs/us/army/us_army_mtMB_23.jpg","description":"1942年～1943年，美军一辆威利吉普车牵引着一门37mm反坦克炮向前线进发，二战期间，美军经常将威利吉普车作为小口径火炮的标准牵引车使用。","caption":""},{"image":"imgs/us/army/us_army_mtMB_24.jpg","description":"1943年3月23日，非洲战场，在突尼斯的盖塔尔（El Guettar）地区附近战斗中，美军第1步兵师的一名战地指挥官坐在一辆威利吉普车上用电话向下属发出指令。","caption":""},{"image":"imgs/us/army/us_army_mtMB_25.jpg","description":"1943年5月，非洲战场突尼斯，停泊在营房的美军一辆威利吉普车，这是一辆由美军第2军军械所改装的早期生产的威利吉普车，车门前侧装备着一挺由转轴支撑的12.7mm口径M2重机枪，车前保险杠还竖着一支杆（防跨越道路时拉动导线产生的伤害）。","caption":""},{"image":"imgs/us/army/us_army_mtMB_26.jpg","description":"1944年1月17日，意大利战场卡西诺山附近，美军第34师的一辆威利吉普车上，炮兵观察兵正在用电台与美军炮兵联络；二战期间，威利吉普车也常被美军作炮兵前沿观察与炮火校正车用。","caption":""},{"image":"imgs/us/army/us_army_mtMB_27.jpg","description":"1944年5月19日，美军一辆装备有重机枪的威利吉普车牵引着一辆装载着美军第85师担架的医疗拖卡经过意大利福米亚（Formia），这天正是该镇被解放的第一天。","caption":""},{"image":"imgs/us/army/us_army_mtMB_28.jpg","description":"1944年6月12日，法国诺曼底，美军第1师第16步兵团士兵驾驶多辆吉普车从大型登陆舰（LCT）驶出，登陆在奥马哈海滩上。在“D”日，该团率先登陆在奥马哈海滩，但总部与支援人员可能要在几天后才能到达。","caption":""},{"image":"imgs/us/army/us_army_mtMB_29.jpg","description":"美军101空降师506步兵团一辆威利吉普车在犹他海滩的一个着陆区附近拉着一辆带供应的手推车，后面是一架滑翔机。","caption":""},{"image":"imgs/us/army/us_army_mtMB_30.jpg","description":"这是美国巴顿将军在1944年至1945年间指挥美第3军时专用的一辆吉普车，编号为W033914，尽管巴顿将军在其军人职业生涯中有过很多辆吉普车，但这辆应是最主要的一辆。这张照片是他在1944年初秋的法国视察美第5装甲师时拍到的。注意：该车的前挡风玻璃显然是加高了。","caption":""},{"image":"imgs/us/army/us_army_mtMB_31.jpg","description":"1945年3月，美军第26师第328步兵团一辆威利吉普车的士兵进入刚结束战斗的德国特里尔（Trier）城镇，正在观看路边一服装店的假人。","caption":""},{"image":"imgs/us/army/us_army_mtMB_32.jpg","description":"1945年1月12日，西线战场比利时霍顿市，一名正在路边做清理工作的比利时女孩向乘坐一辆威利吉普车、担任侦察任务的美军士兵指出开往德国的路标。","caption":""},{"image":"imgs/us/army/us_army_mtMB_33.jpg","description":"1945年1月，西线战场比利时，美军第9步兵师第60步兵侦察分队在加装了防护装甲的威利吉普车上安装了双发火箭发射器，以加强作战火力。","caption":""},{"image":"imgs/us/army/us_army_mtMB_34.jpg","description":"1945年1月13日，西线战场比利时，美军第11装甲师第63装甲步兵营的侦察兵用一辆装备了一挺7.62mm口径M1919重机枪的威利吉普车运送在巴斯托涅行动中捕获的德军俘虏。","caption":""},{"image":"imgs/us/army/us_army_mtMB_35.jpg","description":"1945年太平洋战场，美国第1海军陆战师士兵将威利吉普车停泊在海滩上摆拍。这是一辆装备了一挺7.62mm口径M1919重机枪作侦察用的威利吉普车。虽然，海军陆战队在陆上的机动能力比美国陆军要低，但拥有的吉普车还是很多的。","caption":""},{"image":"imgs/us/army/us_army_mtMB_36.jpg","description":"一辆用威利吉普车改装的担架救护车，其车前安装了一个框架，可容放两付担架；该车在1945年1月的一次突击战中，专门负责美军第84师334步兵团的伤员运送。","caption":""},{"image":"imgs/us/army/us_army_mtMB_37.jpg","description":"除美军外，盟国军队也得到了不少威利吉普车，英军竟然在威利吉普车的小小车厢内装上了一门大炮作火力支援车用，可见威利吉普车的结构性能和负载能力是相当不错的。","caption":""},{"image":"imgs/us/army/us_army_mtMB_38.jpg","description":"苏军根据租借法案也得到了一批美国支援的威利吉普车，图为苏军驾驶的多辆威利吉普车奔驰在苏联草原上。","caption":""}]}')}});